import{_ as t,o,c as a,a2 as r}from"./chunks/framework.vLhlLNVn.js";const s="/assets/detailansicht.iO2JD4_C.png",m=JSON.parse('{"title":"Settings (instance and datapoint)","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/en/03.referenz/01.einstellungen.md"},"headers":[],"relativePath":"adapter/sourceanalytix/referenz/einstellungen.md","filePath":"adapter/sourceanalytix/referenz/einstellungen.md","lastUpdated":null}'),i={name:"adapter/sourceanalytix/referenz/einstellungen.md"};function d(n,e,c,u,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="settings-instance-and-datapoint" tabindex="-1">Settings (instance and datapoint) <a class="header-anchor" href="#settings-instance-and-datapoint" aria-label="Permalink to &quot;Settings (instance and datapoint)&quot;">​</a></h1><p><a id="units-supported-energy-volume-weight"></a></p><h2 id="which-units-are-supported-energy-volume-weight-length" tabindex="-1">Which units are supported (energy, volume, weight, length)? <a class="header-anchor" href="#which-units-are-supported-energy-volume-weight-length" aria-label="Permalink to &quot;Which units are supported (energy, volume, weight, length)?&quot;">​</a></h2><p><strong>In short:</strong> SourceAnalytix knows 30 fixed units for power, energy, volume, mass and length. It converts only within the same quantity, plus between liters and cubic meters. Power is summed up over time to give energy.</p><table tabindex="0"><thead><tr><th>Quantity</th><th>Units</th><th>Converted to</th></tr></thead><tbody><tr><td>Power</td><td><code>GW</code>, <code>MW</code>, <code>kW</code>, <code>W</code>, <code>mW</code></td><td>Energy (<code>GWh</code> to <code>mWh</code>), summed up over time</td></tr><tr><td>Energy</td><td><code>GWh</code>, <code>MWh</code>, <code>kWh</code>, <code>Wh</code>, <code>mWh</code></td><td>any other energy unit</td></tr><tr><td>Volume (cubic)</td><td><code>km³</code>, <code>m³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code></td><td>any other volume unit, including liters</td></tr><tr><td>Volume (liters)</td><td><code>hl</code>, <code>l</code>, <code>dl</code>, <code>cl</code>, <code>ml</code></td><td>any other volume unit, including cubic meters (1 <code>m³</code> = 1,000 <code>l</code>)</td></tr><tr><td>Mass</td><td><code>t</code>, <code>kg</code>, <code>g</code></td><td>any other mass unit</td></tr><tr><td>Length</td><td><code>km</code>, <code>m</code>, <code>dm</code>, <code>cm</code>, <code>mm</code>, <code>µm</code>, <code>nm</code></td><td>any other length unit</td></tr></tbody></table><p>Up to v0.6.1, the characters must be written exactly as shown: <code>m³</code> with a superscript 3, <code>l</code> in lowercase, <code>kWh</code> with a capital W. The spellings that are also recognized from v0.6.2 are listed further down.</p><h3 id="which-unit-applies-where" tabindex="-1">Which unit applies where? <a class="header-anchor" href="#which-unit-applies-where" aria-label="Permalink to &quot;Which unit applies where?&quot;">​</a></h3><p>There are two units, and you need to know both:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td>&quot;Unit&quot; on the source (from v0.7.0 in the source detail, up to v0.6.x in the custom settings dialog of the datapoint under &quot;Select Unit&quot;)</td><td>The unit in which the device <strong>delivers</strong> the value (source unit). The default is &quot;Detect automatically&quot;: SourceAnalytix then uses the unit set on the datapoint&#39;s object.</td></tr><tr><td>&quot;Unit&quot; in the price definition</td><td>The unit in which SourceAnalytix <strong>calculates and displays</strong> (target unit). All consumption states, start values and the price per unit refer to it.</td></tr></tbody></table><p>Examples:</p><ul><li>Your water meter delivers <code>l</code>, the price definition uses <code>m³</code>: 1,000 <code>l</code> become 1 <code>m³</code>.</li><li>Your electricity meter delivers <code>Wh</code>, the price definition uses <code>kWh</code>: 1,000 <code>Wh</code> become 1 <code>kWh</code>.</li><li>Your smart plug delivers <code>W</code>, the price definition uses <code>kWh</code>: SourceAnalytix converts the power into energy over time.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>For a power source (<code>W</code>, <code>kW</code> …), the price definition must use an energy unit (<code>kWh</code>, <code>Wh</code> …). If source and price definition don&#39;t fit together, for example <code>kg</code> and <code>kWh</code> or <code>kWh</code> and <code>W</code>, then up to v0.6.1 SourceAnalytix calculates nothing and writes <code>reading incorrect after conversion contact DEV</code> to the log with every value. With <code>W</code> and <code>m³</code> it calculates wrong values without any message. From v0.6.2 the datapoint does not start, and the log says <code>Unit &lt;unit&gt; of &lt;datapoint&gt; cannot be converted to unit &lt;unit&gt; of price definition &lt;name&gt;</code>.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Up to v0.6.1, SourceAnalytix converts the units <code>km³</code>, <code>dm³</code>, <code>cm³</code>, <code>mm³</code>, <code>µm</code> and <code>nm</code> incorrectly whenever source and price definition use different units. For example, 1,000 <code>dm³</code> become 100 <code>m³</code> instead of 1 <code>m³</code>. For these units, choose the same unit in the price definition as on the datapoint. <code>m³</code>, the liter series and the conversion between <code>l</code> and <code>m³</code> are correct. The bug is fixed from v0.6.2 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a>).</p></div><h3 id="units-outside-the-list" tabindex="-1">Units outside the list <a class="header-anchor" href="#units-outside-the-list" aria-label="Permalink to &quot;Units outside the list&quot;">​</a></h3><p>These are not supported:</p><ul><li>meter readings without a unit, such as pieces or pulses,</li><li>time, for example operating hours in <code>h</code>,</li><li>data sizes such as <code>MB</code> or <code>GB</code>,</li><li>rates such as <code>m³/h</code>, <code>l/min</code> or <code>kg/h</code>,</li><li>all other quantities, for example <code>%</code>, <code>hPa</code>, <code>V</code> or <code>A</code>.</li></ul><p>If the datapoint has such a unit, or none at all, it does not start and the log says <code>No unit defined</code>. If the value is really in a supported unit and only the object is labeled wrongly, select the right unit yourself. From v0.7.0, do this in the source detail under &quot;Unit&quot;, or in the &quot;Problems&quot; tab at &quot;Unit missing or not recognised&quot; with &quot;Fix&quot;. Up to v0.6.x, use the custom settings dialog under &quot;Select Unit&quot;. For the steps, see <a href="./../fehlerbehebung/log-meldungen#error-unit-not-supported-no">Error &quot;unit not supported&quot; / &quot;No unit defined&quot;</a>.</p><p><strong>From v0.7.0</strong>, pieces and pulses are added, see the next section. Time, data sizes, rates such as <code>m³/h</code> and all other quantities stay outside the list.</p><h3 id="pieces-and-pulses-from-v0-7-0" tabindex="-1">Pieces and pulses (from v0.7.0) <a class="header-anchor" href="#pieces-and-pulses-from-v0-7-0" aria-label="Permalink to &quot;Pieces and pulses (from v0.7.0)&quot;">​</a></h3><p>From v0.7.0 there are two more units (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/304" target="_blank" rel="noreferrer">#304</a>, <a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/74" target="_blank" rel="noreferrer">#74</a>):</p><table tabindex="0"><thead><tr><th>Unit</th><th>Used for</th><th>Spellings recognized on the object</th></tr></thead><tbody><tr><td><code>piece</code></td><td>Meter readings without a physical unit, for example burner starts, and pulse counters with the total number of pulses</td><td><code>pcs</code>, <code>pc</code>, <code>pieces</code>, <code>Stk</code>, <code>Stück</code>, <code>imp</code>, <code>impulse</code>, <code>pulses</code></td></tr><tr><td><code>piece/min</code></td><td>Pulses per minute, for example <code>pulses/min</code> on an ESPHome pulse counter. SourceAnalytix sums them up over time, like a power value.</td><td><code>pulses/min</code>, <code>imp/min</code>, <code>pcs/min</code></td></tr></tbody></table><p>Here is how to use them. The fields for pulses are in the source detail: &quot;Pulses per &lt;unit&gt;&quot; in the &quot;Settings&quot; section, as soon as the source delivers in <code>piece</code> or <code>piece/min</code> and the price definition does not calculate in <code>piece</code>, and &quot;Each update adds its value&quot; under &quot;For experts&quot;.</p><ul><li><strong>Just counting</strong>, for example burner starts: Create a price definition with the unit <code>piece</code>. A price per piece is possible but not required.</li><li><strong>Converting pulses to kWh or m³:</strong> At &quot;Pulses per &lt;unit&gt;&quot;, enter how many pulses make up one unit of the price definition. For example, <code>1000</code> for an electricity meter with 1000 imp/kWh and a price definition in kWh. Without this value the source does not start, and the log says <code>Unit piece of &lt;datapoint&gt; cannot be converted to unit kWh of price definition &lt;name&gt;</code>.</li><li><strong>Every update is a pulse:</strong> If the datapoint does not send a meter reading but an update for each pulse, for example <code>1</code>, <code>true</code> or <code>0.001</code> kWh, tick &quot;Each update adds its value&quot;. Every update then counts, even if the value does not change (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/479" target="_blank" rel="noreferrer">#479</a>). Negative values are ignored, and the value already in the datapoint when SourceAnalytix starts is not counted again.</li></ul><p>A source in <code>piece/min</code> and a source with &quot;Each update adds its value&quot; keep their total themselves, like a power source: it starts at 0, there is no reset detection, and you leave the start values empty. A source in <code>piece</code> with the total number of pulses behaves like a meter reading, with reset detection.</p><p><strong>From v0.6.2:</strong> SourceAnalytix also recognizes variant spellings on the object (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1264" target="_blank" rel="noreferrer">#1264</a>): <code>m3</code>, <code>M3</code> and <code>m^3</code> count as <code>m³</code>, <code>kwh</code> and <code>KWH</code> as <code>kWh</code>, <code>L</code> as <code>l</code>. A spelling that matches two units is not reinterpreted: <code>mwh</code> could be <code>MWh</code> or <code>mWh</code>. Spelled-out names such as <code>Liter</code> or <code>Watt</code> are still not recognized. When a spelling is reinterpreted, the log says, for example, <code>Unit &quot;m3&quot; of &lt;datapoint&gt; is used as m³</code>. The settings dialog also accepts these spellings with &quot;Detect automatically&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1278" target="_blank" rel="noreferrer">#1278</a>).</p><p><strong>See also:</strong> <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Which unit do I set on the datapoint (kWh instead of Wh, m³ instead of liters)?</a> · <a href="./../erste-schritte/erster-zaehler#start-values-unit">Start values and their unit</a> · <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a></p><p><a id="instance-settings-exist-periods-decimals"></a></p><h2 id="which-instance-settings-are-there-periods-decimals" tabindex="-1">Which instance settings are there (periods, decimals)? <a class="header-anchor" href="#which-instance-settings-are-there-periods-decimals" aria-label="Permalink to &quot;Which instance settings are there (periods, decimals)?&quot;">​</a></h2><p><strong>In short:</strong> From v0.7.0, the SourceAnalytix instance settings have four tabs. In &quot;Main settings&quot; you decide which week, month and quarter states are created and how many decimals new sources get. If a state is missing, the matching option there is usually off, or &quot;Consumption&quot;, &quot;Costs&quot; or &quot;Store meter readings&quot; is not ticked on the source.</p><h3 id="the-tabs-from-v0-7-0" tabindex="-1">The tabs (from v0.7.0) <a class="header-anchor" href="#the-tabs-from-v0-7-0" aria-label="Permalink to &quot;The tabs (from v0.7.0)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th><th>When a change takes effect</th></tr></thead><tbody><tr><td>&quot;Overview&quot;</td><td>All sources with status, total and the values for &quot;Today&quot;, &quot;Month&quot; and &quot;Year&quot;. &quot;Add source&quot; starts the wizard, a click on a source opens its source detail.</td><td>Actions marked with ⚡ immediately, without saving and without a restart</td></tr><tr><td>&quot;Problems&quot;</td><td>Checks all sources and suggests a fix for each finding</td><td>immediately</td></tr><tr><td>&quot;Price definitions&quot;</td><td>Table of prices, see <a href="#price-definition-structured-categories-base">How is a price definition structured (categories, basic fee, decimal mark)?</a></td><td>after &quot;Save&quot;, the instance restarts</td></tr><tr><td>&quot;Main settings&quot;</td><td>Year statistics, current year, rounding (see below)</td><td>after &quot;Save&quot;, the instance restarts</td></tr></tbody></table><p>&quot;Overview&quot; and &quot;Problems&quot; query the running instance. If it is stopped, they show &quot;Instance is not running&quot; and the immediate actions are locked. For what the source detail contains, see <a href="#datapoint-settings-costs-consumption-meter">What do the datapoint settings do (Costs, Consumption, Meter values)?</a>.</p><p><strong>Up to v0.6.x</strong> there are only the tabs &quot;Main settings&quot; and &quot;Price definitions&quot;. You set up sources there in the custom settings dialog of the datapoint.</p><h3 id="main-settings-tab" tabindex="-1">&quot;Main settings&quot; tab <a class="header-anchor" href="#main-settings-tab" aria-label="Permalink to &quot;&quot;Main settings&quot; tab&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Section</th><th>Option</th><th>Default</th><th>What SourceAnalytix creates</th></tr></thead><tbody><tr><td>&quot;Year statistics&quot;</td><td>&quot;Weeks&quot;</td><td>off</td><td>Archive <code>&lt;device&gt;.&lt;year&gt;.&lt;category&gt;.weeks.01</code> to <code>53</code></td></tr><tr><td>&quot;Year statistics&quot;</td><td>&quot;Months&quot;</td><td>on</td><td>Archive <code>&lt;device&gt;.&lt;year&gt;.&lt;category&gt;.months.01_January</code> to <code>12_December</code></td></tr><tr><td>&quot;Year statistics&quot;</td><td>&quot;Quarters&quot;</td><td>off</td><td>Archive <code>&lt;device&gt;.&lt;year&gt;.&lt;category&gt;.quarters.Q1</code> to <code>Q4</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Weekday&quot;</td><td>on</td><td><code>currentYear.&lt;category&gt;.currentWeek.01_Monday</code> to <code>07_Sunday</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Weeks&quot;</td><td>on</td><td><code>currentYear.&lt;category&gt;.weeks.01</code> to <code>53</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Months&quot;</td><td>on</td><td><code>currentYear.&lt;category&gt;.months.01_January</code> to <code>12_December</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Quarters&quot;</td><td>on</td><td><code>currentYear.&lt;category&gt;.quarters.Q1</code> to <code>Q4</code></td></tr><tr><td>&quot;Current year&quot;</td><td>&quot;Previous period&quot;</td><td>on</td><td><code>01_previousDay</code> to <code>05_previousYear</code>, with &quot;Weekday&quot; also <code>previousWeek.01_Monday</code> to <code>07_Sunday</code></td></tr><tr><td>&quot;Rounding&quot;</td><td>&quot;Decimals for consumption values&quot;</td><td>3</td><td>Template for new sources</td></tr><tr><td>&quot;Rounding&quot;</td><td>&quot;Decimals for cost values&quot;</td><td>2</td><td>Template for new sources</td></tr></tbody></table><p><strong>Up to v0.6.x</strong>, the German interface calls the &quot;Quarters&quot; option &quot;Viertel&quot;.</p><p><code>&lt;category&gt;</code> is <code>consumed</code> or <code>delivered</code> for consumption, <code>costs</code> or <code>earnings</code> for money, and <code>meterReadings</code> for meter readings. If any of the three &quot;Year statistics&quot; options is on, the year folder also contains the yearly totals <code>&lt;year&gt;.consumedCumulative</code> (or <code>deliveredCumulative</code>), <code>&lt;year&gt;.costsCumulative</code> (or <code>earningsCumulative</code>) and the meter reading <code>&lt;year&gt;.readingCumulative</code>. For what each state contains, see <a href="./states-und-meldungen#week-month-quarter-states-weekdays">Which week, month and quarter states and weekdays are there?</a>.</p><h3 id="why-some-states-are-missing" tabindex="-1">Why some states are missing <a class="header-anchor" href="#why-some-states-are-missing" aria-label="Permalink to &quot;Why some states are missing&quot;">​</a></h3><ul><li><strong>The option is off.</strong> SourceAnalytix then does not create the states. If you turn an option off, it deletes the existing states of the current year the next time the source starts, that is, when the instance restarts after you save.</li><li><strong>The checkbox is missing on the source.</strong> Consumption states exist only with &quot;Consumption&quot;, cost states only with &quot;Costs&quot;, meter readings only with &quot;Store meter readings&quot;.</li><li><strong>The week belongs to the next year.</strong> From 29 to 31 December, calendar week 01 of the new year may already be running. It is not written under <code>currentYear.&lt;category&gt;.weeks</code>, see <a href="./../hintergrund/perioden-und-zeit#week-52-53-have-values">Why does week 52/53 show values in the new year?</a>.</li><li><strong>The first period rollover is still to come.</strong> Until then, the previous-period states stay at 0, see <a href="./states-und-meldungen#yesterday-last-week-last-month">Where do I find yesterday, last week, last month (previous states)?</a>.</li></ul><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If you turn off &quot;Weeks&quot;, &quot;Months&quot;, &quot;Quarters&quot;, &quot;Weekday&quot; or &quot;Previous period&quot;, the values of the current year in these states are gone. Recordings in a history adapter and the year folders of earlier years are kept.</p></div><h3 id="decimals" tabindex="-1">Decimals <a class="header-anchor" href="#decimals" aria-label="Permalink to &quot;Decimals&quot;">​</a></h3><p>The two values under &quot;Rounding&quot; are only a template. Each source takes them over once when it is created and stores its own decimals. If you change the template later, existing sources keep their value. From v0.7.0, you change a source&#39;s decimals in its source detail under &quot;For experts&quot;: &quot;Decimals for consumption&quot; and &quot;Decimals for costs&quot;.</p><ul><li>You can use 0 to 15. With -1, SourceAnalytix stores the value unrounded. Larger numbers count as 15, any negative number as -1.</li><li>Only the states that are written get rounded. The total in <code>cumulativeReading</code> stays unrounded.</li><li>Meter readings under <code>meterReadings</code> are rounded with the decimals for consumption values.</li></ul><p><strong>See also:</strong> <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#so-many-decimals">Why so many decimal places?</a> · <a href="./states-und-meldungen#happens-turn-year">What happens at the turn of the year?</a> · <a href="./../anleitungen/werte-auswerten#evaluate-across-years-adjusting-everything">How do I evaluate values across several years without adjusting everything every year?</a></p><p><a id="datapoint-settings-costs-consumption-meter"></a></p><h2 id="what-do-the-datapoint-settings-do-costs-consumption-meter-values" tabindex="-1">What do the datapoint settings do (Costs, Consumption, Meter values)? <a class="header-anchor" href="#what-do-the-datapoint-settings-do-costs-consumption-meter-values" aria-label="Permalink to &quot;What do the datapoint settings do (Costs, Consumption, Meter values)?&quot;">​</a></h2><p><strong>In short:</strong> Each source has its own settings: price definition, unit and the checkboxes &quot;Consumption&quot;, &quot;Costs&quot; and &quot;Store meter readings&quot;, which decide which states are created. From v0.7.0, you set them in the wizard when you add the source and change them later in the source detail. &quot;Apply&quot; takes effect immediately, without a restart.</p><h3 id="how-to-get-to-the-settings-from-v0-7-0" tabindex="-1">How to get to the settings (from v0.7.0) <a class="header-anchor" href="#how-to-get-to-the-settings-from-v0-7-0" aria-label="Permalink to &quot;How to get to the settings (from v0.7.0)&quot;">​</a></h3><ol><li>Open the SourceAnalytix instance settings, &quot;Overview&quot; tab.</li><li>Click the source. At the top, the source detail shows datapoint, type, total, price and &quot;Last update&quot;. Below are the sections &quot;Values&quot;, &quot;Settings&quot; and &quot;Actions&quot;.</li><li>Change the fields in the &quot;Settings&quot; section. More fields are under &quot;For experts&quot;.</li><li>Click &quot;Apply&quot;. If a field is invalid, the page marks it and saves nothing.</li></ol><p><img src="'+s+'" alt="Detail view of a source with &quot;Values&quot;, &quot;Settings&quot; and &quot;Actions&quot;"></p><h3 id="all-settings-of-a-source" tabindex="-1">All settings of a source <a class="header-anchor" href="#all-settings-of-a-source" aria-label="Permalink to &quot;All settings of a source&quot;">​</a></h3><p>The &quot;Default&quot; column shows what the wizard pre-fills. For those switching over, the last column gives the name of the field in the custom settings dialog of the datapoint up to v0.6.x.</p><table tabindex="0"><thead><tr><th>Setting (from v0.7.0)</th><th>Effect</th><th>Default</th><th>Up to v0.6.x in the custom settings dialog</th></tr></thead><tbody><tr><td>&quot;Name&quot;</td><td>Display name of the source&#39;s folder. Does not change any state ID, see <a href="#name-datapoint-alias-output-id">How do I name the datapoint (alias, output ID)?</a></td><td>Name of the datapoint</td><td>&quot;Name&quot;</td></tr><tr><td>&quot;Unit&quot;</td><td>Unit in which the datapoint delivers. &quot;Detect automatically&quot; uses the unit on the object, see <a href="#units-supported-energy-volume-weight">Which units are supported (energy, volume, weight, length)?</a></td><td>detected unit</td><td>&quot;Select Unit&quot;</td></tr><tr><td>&quot;Price definition&quot;</td><td>Required. Sets the target unit and whether consumption and costs or feed-in and earnings are counted</td><td>–</td><td>&quot;Select price definition&quot;</td></tr><tr><td>&quot;Consumption&quot;</td><td>States under <code>currentYear.consumed</code> or <code>currentYear.delivered</code></td><td>on</td><td>&quot;Calculate consumption&quot;</td></tr><tr><td>&quot;Costs&quot;</td><td>States under <code>currentYear.costs</code> or <code>currentYear.earnings</code></td><td>on</td><td>&quot;Calculate costs&quot;</td></tr><tr><td>&quot;Include basic fee&quot;</td><td>Books the &quot;Price per month&quot; of the price definition into the costs. Works only with &quot;Costs&quot;</td><td>on, unless another source of the same price definition already books it</td><td>&quot;Including basic rate&quot;</td></tr><tr><td>&quot;Store meter readings&quot;</td><td>Meter readings per period under <code>currentYear.meterReadings</code></td><td>on</td><td>&quot;Store Meter Values&quot;</td></tr><tr><td>&quot;Reset detection&quot;</td><td>Catches drops of the meter to 0, see <a href="#threshold-disabling-reset-detection-work">Threshold and turning off reset detection</a></td><td>depends on the answer to &quot;Does the value sometimes drop to 0 …?&quot;</td><td>&quot;Device value reset detection Enabled&quot;</td></tr><tr><td>&quot;Ignore negative values&quot;</td><td>Power only: Negative values count as 0 W, for example with inverters at night</td><td>off</td><td>&quot;Ignore negative power values&quot;</td></tr><tr><td>&quot;Reset detection threshold (&lt;unit&gt;)&quot; under &quot;For experts&quot;</td><td>Largest drop that still counts as measurement noise</td><td>1</td><td>&quot;Threshold&quot;</td></tr><tr><td>&quot;Decimals for consumption&quot; / &quot;Decimals for costs&quot; under &quot;For experts&quot;</td><td>Rounding of the states that are written, see <a href="#instance-settings-exist-periods-decimals">Instance settings</a></td><td>Template of the instance (3 / 2)</td><td>&quot;Decimals for consumption values&quot; / &quot;… cost values&quot;</td></tr></tbody></table><p>These settings appear only for matching sources, or the wizard does not ask for them. From v0.7.0 they are all in the source detail (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1285" target="_blank" rel="noreferrer">#1285</a>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Where in the source detail</th><th>Effect</th><th>Default</th></tr></thead><tbody><tr><td>&quot;Technical ID&quot;</td><td>under &quot;For experts&quot;, also in the wizard</td><td>Name of the folder <code>sourceanalytix.0.&lt;device&gt;</code>. Letters, digits, <code>_</code> and <code>-</code> are allowed. Changing it moves all values to the new folder, see <a href="#name-datapoint-alias-output-id">How do I name the datapoint (alias, output ID)?</a></td><td>derived from the name</td></tr><tr><td>&quot;Average power values&quot;</td><td>for power sources, also in the wizard</td><td>Calculates each interval with the average of the old and new value instead of the old value</td><td>off</td></tr><tr><td>&quot;Maximum gap between power values (minutes)&quot;</td><td>for power sources</td><td>Longer pauses without a new power value count as 0 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1266" target="_blank" rel="noreferrer">#1266</a>)</td><td>empty = off</td></tr><tr><td>&quot;Pulses per &lt;unit&gt;&quot;</td><td>for sources in <code>piece</code> or <code>piece/min</code> whose price definition does not calculate in <code>piece</code></td><td>Converts pulses into the target unit, for example <code>1000</code> for 1000 imp/kWh</td><td>empty</td></tr><tr><td>&quot;Each update adds its value&quot;</td><td>under &quot;For experts&quot;</td><td>Every update counts as an increment instead of a meter reading</td><td>off</td></tr><tr><td>&quot;Start values&quot; &quot;Day&quot; to &quot;Year&quot;</td><td>separate &quot;Start values&quot; section, in the wizard only for meter readings</td><td>Total at the beginning of the running period, see <a href="./../erste-schritte/erster-zaehler#start-values-unit">Start values</a></td><td>empty = &quot;Count from now&quot;</td></tr></tbody></table><p>You can enter numbers with a comma or a dot. A single comma or a single dot is always the decimal mark: <code>1.283</code> is read as 1.283, not as 1283. The source detail checks the start values like the wizard does. As long as a start value shows an error, &quot;⚡ Apply&quot; stays locked.</p><p><strong>From v0.7.0:</strong> In the custom settings dialog of the datapoint (tab &quot;Objects&quot;, wrench icon) there is only the &quot;enabled&quot; checkbox, a hint and the button &quot;Open SourceAnalytix settings&quot;. If you switch a source on there, SourceAnalytix sets &quot;Consumption&quot;, &quot;Costs&quot;, &quot;Store meter readings&quot; and &quot;Reset detection&quot; with threshold 1. Because no price definition is chosen yet, the source appears in the &quot;Problems&quot; tab with &quot;No price definition selected&quot;. Existing settings stay unchanged (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1286" target="_blank" rel="noreferrer">#1286</a>).</p><p><strong>Up to v0.6.x:</strong> If you add a new source in the custom settings dialog, &quot;Calculate consumption&quot;, &quot;Calculate costs&quot; and &quot;Store Meter Values&quot; are not pre-ticked. Without these checkboxes, SourceAnalytix maintains only <code>cumulativeReading</code> and <code>statisticsJson</code>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>If you untick &quot;Consumption&quot;, &quot;Costs&quot; or &quot;Store meter readings&quot; again, SourceAnalytix deletes the matching states of the source. Recordings in a history adapter are kept.</p></div><h3 id="when-the-meterreadings-folder-stays-empty" tabindex="-1">When the <code>meterReadings</code> folder stays empty <a class="header-anchor" href="#when-the-meterreadings-folder-stays-empty" aria-label="Permalink to &quot;When the `meterReadings` folder stays empty&quot;">​</a></h3><p><code>meterReadings</code> holds the total at the end of a period, not the consumption. It stays empty or incomplete if:</p><ul><li>&quot;Store meter readings&quot; is off,</li><li>you are looking for the current reading: There is no state <code>meterReadings.01_currentDay</code>, the current reading is in <code>cumulativeReading</code>,</li><li>&quot;Weekday&quot;, &quot;Weeks&quot;, &quot;Months&quot;, &quot;Quarters&quot; or &quot;Previous period&quot; are off in the instance settings, because meter readings are created only for these periods,</li><li>the first period rollover is still to come: <code>01_previousDay</code> and the other previous periods are filled only then.</li></ul><p><strong>Up to v0.6.1</strong>, a meter reading of exactly 0 is not written under <code>meterReadings</code>. This is fixed from v0.6.2 (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1253" target="_blank" rel="noreferrer">#1253</a>).</p><p><strong>Up to v0.6.x</strong> there is no source detail. All settings are then in the custom settings dialog of the datapoint, as described in <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Where do I configure SourceAnalytix for a datapoint?</a>.</p><p><strong>See also:</strong> <a href="./states-und-meldungen#meter-readings-cumulative">Why are meter readings cumulative?</a> · <a href="#source-types-exist-meter-power">Which source types are there (meter, power)?</a> · <a href="./../fehlerbehebung/log-meldungen#datapoint-enabled-but-no-folders">Datapoint enabled but no folders are created</a></p><p><a id="threshold-disabling-reset-detection-work"></a></p><h2 id="how-do-the-threshold-and-turning-off-reset-detection-work" tabindex="-1">How do the threshold and turning off reset detection work? <a class="header-anchor" href="#how-do-the-threshold-and-turning-off-reset-detection-work" aria-label="Permalink to &quot;How do the threshold and turning off reset detection work?&quot;">​</a></h2><p><strong>In short:</strong> You set reset detection and its threshold separately for each source. Leave detection on if your meter can start at 0 after a restart or power failure. The threshold (default 1, in the target unit) is the largest drop that still counts as measurement noise. Turning detection off is meant only for sources that are allowed to drop on purpose.</p><h3 id="how-to-set-it-from-v0-7-0" tabindex="-1">How to set it (from v0.7.0) <a class="header-anchor" href="#how-to-set-it-from-v0-7-0" aria-label="Permalink to &quot;How to set it (from v0.7.0)&quot;">​</a></h3><ol><li>In the instance settings, &quot;Overview&quot; tab, open the source.</li><li>In the &quot;Settings&quot; section, tick or untick &quot;Reset detection&quot;.</li><li>Click &quot;For experts&quot; and enter the threshold in the target unit under &quot;Reset detection threshold (&lt;unit&gt;)&quot;, for example <code>0.5</code> for 0.5 kWh.</li><li>Click &quot;Apply&quot;.</li></ol><p>When you add a source, the wizard asks: &quot;Does the value sometimes drop to 0, e.g. after a power failure?&quot; With &quot;Yes&quot;, reset detection is on, with &quot;No&quot; it is off. &quot;No&quot; is preselected, and &quot;Yes&quot; for Shelly or Tasmota datapoints.</p><h3 id="what-happens-when-the-value-drops" tabindex="-1">What happens when the value drops <a class="header-anchor" href="#what-happens-when-the-value-drops" aria-label="Permalink to &quot;What happens when the value drops&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Drop in the device value</th><th>Reset detection on</th><th>Reset detection off</th></tr></thead><tbody><tr><td>at most the threshold</td><td>Measurement noise: The value is ignored, the total stays where it is</td><td>The total drops with it</td></tr><tr><td>more than the threshold</td><td>Possible reset: SourceAnalytix waits for the next value and then continues with a new offset</td><td>The total drops with it, and the consumption of the periods can go negative</td></tr></tbody></table><p>For the details of how a reset is confirmed, see <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a>. Measurement noise appears only in the debug log (&quot;Ignoring cumulative reading jitter&quot;).</p><h3 id="which-threshold-fits" tabindex="-1">Which threshold fits? <a class="header-anchor" href="#which-threshold-fits" aria-label="Permalink to &quot;Which threshold fits?&quot;">​</a></h3><ul><li><strong>Larger than the normal noise</strong> of the device, so that small drops don&#39;t count as a reset.</li><li><strong>Smaller than the value the device starts from again after a reset or swap.</strong> If a meter falls only slightly below its old value, it is otherwise not detected as a reset.</li><li><strong>0</strong> means: Every drop is a possible reset.</li></ul><p>Threshold and reset detection work only for meter readings. For power sources (W), for <code>piece/min</code> and for &quot;Each update adds its value&quot;, SourceAnalytix keeps the total itself, so there is no reset detection there. That is why the wizard does not show the threshold for power.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>With &quot;No&quot; in the wizard, reset detection is off. If such a meter does drop to 0 once, the total drops with it and the values of the running periods turn negative. The &quot;Problems&quot; tab then reports &quot;Meter drops to 0, reset detection is off&quot; and offers &quot;Switch on&quot;. To correct the values afterwards, see <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Correct wrong values</a>.</p></div><p><strong>From v0.6.2:</strong> The message &quot;Cumulative reading for … decreased while reset detection is disabled&quot; appears only in the debug log. Up to v0.6.1 it appeared in the info log with every drop (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1262" target="_blank" rel="noreferrer">#1262</a>).</p><p><strong>Up to v0.6.x</strong> you set both in the custom settings dialog of the datapoint: &quot;Device value reset detection Enabled&quot; (default on) and &quot;Threshold&quot; (default 1).</p><p><strong>See also:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#meter-restarts-after-power-loss">My meter starts at 0 after a power failure</a> · <a href="./../hintergrund/zaehler-reset#counter-reset-0-daily-happens">Counter that is reset to 0 every day</a> · <a href="./../anleitungen/zaehlerstaende-korrigieren#replaced-meter-device-avoid-negative">Meter or device replaced</a></p><p><a id="price-definition-structured-categories-base"></a></p><h2 id="how-is-a-price-definition-structured-categories-basic-fee-decimal-mark" tabindex="-1">How is a price definition structured (categories, basic fee, decimal mark)? <a class="header-anchor" href="#how-is-a-price-definition-structured-categories-basic-fee-decimal-mark" aria-label="Permalink to &quot;How is a price definition structured (categories, basic fee, decimal mark)?&quot;">​</a></h2><p><strong>In short:</strong> A price definition is one row in the &quot;Price definitions&quot; tab of the instance settings. It has a freely chosen name (&quot;Category&quot;), a unit, a cost type and a price. Each source gets exactly one price definition. The monthly basic fee is booked in full, once per month, not pro rata per day.</p><h3 id="the-fields" tabindex="-1">The fields <a class="header-anchor" href="#the-fields" aria-label="Permalink to &quot;The fields&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th></tr></thead><tbody><tr><td>&quot;Category&quot;</td><td>Name of the price definition, for example <code>electricity</code> or <code>heatpump</code>. You use it to select the price definition on the source. Each name may appear only once.</td></tr><tr><td>&quot;Description&quot;</td><td>Free text, just for you</td></tr><tr><td>&quot;Cost Type&quot;</td><td>&quot;Costs&quot; for consumption from the grid (consumption and costs) or &quot;Earnings&quot; for feed-in and earnings. Decides whether the values are under <code>consumed</code> and <code>costs</code> or under <code>delivered</code> and <code>earnings</code>.</td></tr><tr><td>&quot;Unit&quot;</td><td>The target unit: SourceAnalytix calculates and displays everything in it for the sources of this price definition</td></tr><tr><td>&quot;Price source&quot;</td><td>&quot;Fixed price&quot;, &quot;Datapoint&quot; or &quot;Tariff selector&quot;, see below</td></tr><tr><td>&quot;Price per unit&quot;</td><td>Price per target unit, for example <code>0.32</code> for 0.32 €/kWh</td></tr><tr><td>&quot;Price state&quot;</td><td>Only with &quot;Datapoint&quot; and &quot;Tariff selector&quot;: the state that delivers the price or the tariff</td></tr><tr><td>&quot;Active tariff price&quot;</td><td>Only with &quot;Tariff selector&quot;: price while the tariff is active</td></tr><tr><td>&quot;Active selector value&quot;</td><td>Only with &quot;Tariff selector&quot;: value of the price state at which the tariff is active</td></tr><tr><td>&quot;Valid from&quot;</td><td>From when price and basic fee apply, starting at 0:00 of that day</td></tr><tr><td>&quot;Price per month&quot;</td><td>Basic fee per month</td></tr></tbody></table><p>If a category appears twice, only the last row counts. In state IDs, every character except letters, digits, <code>_</code> and <code>-</code> is replaced by <code>_</code>.</p><h3 id="price-source" tabindex="-1">Price source <a class="header-anchor" href="#price-source" aria-label="Permalink to &quot;Price source&quot;">​</a></h3><table tabindex="0"><thead><tr><th>&quot;Price source&quot;</th><th>Where the price comes from</th></tr></thead><tbody><tr><td>&quot;Fixed price&quot;</td><td>From &quot;Price per unit&quot;. A new price applies from &quot;Valid from&quot; or, without a date, from the moment you save. SourceAnalytix does not recalculate older values by itself.</td></tr><tr><td>&quot;Datapoint&quot;</td><td>From the &quot;Price state&quot;, for example a dynamic electricity price in €/kWh. Every change is stored with its timestamp. If the state is empty at startup, &quot;Price per unit&quot; serves as a fallback.</td></tr><tr><td>&quot;Tariff selector&quot;</td><td>A state switches between &quot;Price per unit&quot; and &quot;Active tariff price&quot;. Without an &quot;Active selector value&quot;, the tariff counts as active for <code>true</code>, for a number other than 0 and for any text except <code>0</code>, <code>false</code>, <code>off</code>, <code>no</code>, <code>closed</code> or empty. With a selector value, the state must have exactly that value.</td></tr></tbody></table><p>If the price changes between two values of the source, SourceAnalytix splits the consumption between the old and new price according to time. To change a price from a certain date and recalculate costs afterwards, see <a href="./../anleitungen/preise-und-kosten#costs-recalculated-change-price-change">Are calculated costs recalculated when I change the price, and how do I change it from a certain date?</a>. Dynamic prices and day/night tariffs are explained in <a href="./../anleitungen/preise-und-kosten#use-dynamic-electricity-price-tibber">Dynamic electricity price</a> and <a href="./../anleitungen/preise-und-kosten#bill-day-night-tariff">Day/night tariff</a>.</p><h3 id="basic-fee-in-full-once-a-month" tabindex="-1">Basic fee: in full, once a month <a class="header-anchor" href="#basic-fee-in-full-once-a-month" aria-label="Permalink to &quot;Basic fee: in full, once a month&quot;">​</a></h3><ul><li>The &quot;Price per month&quot; is booked in full: once on the day it takes effect, then on the 1st of every month at 0:00. It is not spread over the days.</li><li>In the daily and weekly values, the whole amount therefore appears only on the day and in the week of the booking.</li><li>If you did not enter a &quot;Valid from&quot;, the basic fee applies from 1 January of the current year when you first set up the source. The yearly value then includes all months since January.</li><li>It counts only for sources with &quot;Include basic fee&quot; and &quot;Costs&quot;. Each of these sources books it in full. If two sources of the same price definition have the checkbox ticked, it is counted twice.</li></ul><p><strong>From v0.7.0:</strong> If another source already books the basic fee of the same price definition, the wizard and the &quot;Problems&quot; tab warn you (&quot;Basic fee is booked twice&quot;, with &quot;Switch off here&quot;). At startup, there is also a hint in the log (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1268" target="_blank" rel="noreferrer">#1268</a>). To assign the basic fee correctly, see <a href="./../anleitungen/preise-und-kosten#include-monthly-base-fee">How do I include a monthly basic fee?</a>.</p><h3 id="comma-or-dot" tabindex="-1">Comma or dot? <a class="header-anchor" href="#comma-or-dot" aria-label="Permalink to &quot;Comma or dot?&quot;">​</a></h3><p>SourceAnalytix reads both: <code>0,32</code> and <code>0.32</code> give the same price. This applies to prices from the table, from a price state and to values written to <code>currentPrice</code>. Leave out the thousands separator. After saving, you can check that the price arrived correctly in the state <code>sourceanalytix.0.priceDefinitions.&lt;category&gt;.currentPrice</code>.</p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>If a price is not a number, SourceAnalytix calculates with 0 and writes <code>Price definition &lt;category&gt; has no valid unit price …, using 0 to avoid invalid cost calculations</code> to the log. The costs then stay 0.</p></div><p>A new or changed price definition takes effect only after &quot;Save&quot;, which restarts the instance. Only then can you select it on a source.</p><p><strong>See also:</strong> <a href="./../anleitungen/preise-und-kosten#assign-prices-create-custom-tariffs">How do I assign prices and create my own tariffs (e.g. heat pump)?</a> · <a href="./states-und-meldungen#prices-read-written-as-states">How can I read and set prices as states?</a> · <a href="./../fehlerbehebung/falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Costs stay 0</a></p><p><a id="name-datapoint-alias-output-id"></a></p><h2 id="how-do-i-name-the-datapoint-alias-output-id" tabindex="-1">How do I name the datapoint (alias, output ID)? <a class="header-anchor" href="#how-do-i-name-the-datapoint-alias-output-id" aria-label="Permalink to &quot;How do I name the datapoint (alias, output ID)?&quot;">​</a></h2><p><strong>In short:</strong> A source has two names. The &quot;Name&quot; is only the display name and you can change it at any time. The &quot;Technical ID&quot; is the folder <code>sourceanalytix.0.&lt;device&gt;</code> that holds all the source&#39;s states. It&#39;s best to set it when you add the source, because changing it later moves the whole folder, and you then have to adjust scripts, VIS and history queries.</p><table tabindex="0"><thead><tr><th></th><th>&quot;Name&quot;</th><th>&quot;Technical ID&quot;</th></tr></thead><tbody><tr><td>Affects</td><td>Display name of the folder and <code>source.name</code> in <code>statisticsJson</code></td><td>State IDs: <code>sourceanalytix.0.&lt;device&gt;.cumulativeReading</code>, <code>sourceanalytix.0.&lt;device&gt;.currentYear.…</code></td></tr><tr><td>In the wizard (from v0.7.0)</td><td>Step &quot;Name&quot;</td><td>under &quot;For experts&quot; in the step &quot;Name&quot;; pre-filled from the name, for example <code>house_power</code> from &quot;House Power&quot;</td></tr><tr><td>In the source detail (from v0.7.0)</td><td>&quot;Name&quot; under &quot;Settings&quot;</td><td>&quot;Technical ID&quot; under &quot;Settings&quot;, &quot;For experts&quot;</td></tr><tr><td>Up to v0.6.x in the custom settings dialog</td><td>&quot;Name&quot;</td><td>&quot;Output ID&quot;, pre-filled from the datapoint&#39;s ID, dots become <code>__</code></td></tr><tr><td>Left empty</td><td>Name of the datapoint, without a name <code>No name known, please provide alias</code></td><td>ID of the datapoint with <code>__</code> instead of dots</td></tr></tbody></table><h3 id="rules-for-the-technical-id" tabindex="-1">Rules for the technical ID <a class="header-anchor" href="#rules-for-the-technical-id" aria-label="Permalink to &quot;Rules for the technical ID&quot;">​</a></h3><ul><li>Letters, digits, <code>_</code> and <code>-</code> are allowed, up to 128 characters. The wizard&#39;s suggestion uses only lowercase letters, digits and <code>_</code>.</li><li>The ID must be unique. If another source already uses it, you can&#39;t save (&quot;Another source already uses this ID.&quot;).</li><li><code>info</code>, <code>priceDefinitions</code>, <code>priceHistory</code> and <code>basicPriceHistory</code> are reserved, because SourceAnalytix creates its own states there.</li></ul><h3 id="if-you-change-the-technical-id" tabindex="-1">If you change the technical ID <a class="header-anchor" href="#if-you-change-the-technical-id" aria-label="Permalink to &quot;If you change the technical ID&quot;">​</a></h3><p>You change the ID in the source&#39;s source detail under &quot;For experts&quot; in the &quot;Technical ID&quot; field and click &quot;⚡ Apply&quot;. Below the field it then says &quot;Applying moves all values to the new folder. Scripts, visualisations and history queries must be adjusted.&quot; SourceAnalytix copies the whole folder with all objects and values to the new ID, checks the copy and only then deletes the old folder. While it copies, the source does not calculate. The log says <code>Migrated SourceAnalytix output for &lt;datapoint&gt; from &lt;old ID&gt; to &lt;new ID&gt;</code>.</p><p>If that fails, SourceAnalytix keeps the old ID and reports <code>Cannot use output ID &quot;&lt;new ID&gt;&quot; for &lt;datapoint&gt;: &lt;reason&gt;; keeping &quot;&lt;old ID&gt;&quot;</code>. If the instance stops in the middle of the move, SourceAnalytix cleans up at the next start and tries again.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>After the move, scripts, VIS views, aliases and history queries still point to the old ID. Adjust them by hand. Values that a history adapter recorded before the move stay stored under the old ID.</p></div><p>Using a different datapoint as the source while keeping the data is not possible yet. In the source detail, the action &quot;Switch datapoint&quot; is therefore shown as &quot;planned&quot; (<a href="https://github.com/DrozmotiX/ioBroker.sourceanalytix/issues/1271" target="_blank" rel="noreferrer">#1271</a>).</p><p><strong>See also:</strong> <a href="./../erste-schritte/erster-zaehler#values-consumption-today-yesterday">Where do I find my values (daily consumption today/yesterday)?</a> · <a href="./states-und-meldungen#migrating-older-versions-legacy-settings">Migrating from older versions and leftovers</a> · <a href="./../anleitungen/werte-auswerten#read-sourceanalytix-values-script">How do I read SourceAnalytix values in a script?</a></p><p><a id="source-types-exist-meter-power"></a></p><h2 id="which-source-types-are-there-meter-power" tabindex="-1">Which source types are there (meter, power)? <a class="header-anchor" href="#which-source-types-are-there-meter-power" aria-label="Permalink to &quot;Which source types are there (meter, power)?&quot;">​</a></h2><p><strong>In short:</strong> There are two kinds of sources. A <strong>meter reading</strong> keeps rising, and SourceAnalytix calculates the consumption from the difference. A <strong>power</strong> value shows the instantaneous reading, and SourceAnalytix sums it up over time and keeps the total itself. Which kind a source is follows from its unit.</p><table tabindex="0"><thead><tr><th></th><th>Meter reading</th><th>Power</th></tr></thead><tbody><tr><td>Units</td><td>Energy (<code>Wh</code>, <code>kWh</code> …), volume (<code>m³</code>, <code>l</code> …), mass, length, <code>piece</code></td><td>Power (<code>W</code>, <code>kW</code> …) and <code>piece/min</code></td></tr><tr><td>Display in the source detail (from v0.7.0)</td><td>&quot;Meter reading · kWh&quot;</td><td>&quot;Power · W → kWh&quot;</td></tr><tr><td>Total <code>cumulativeReading</code></td><td>Device value + offset</td><td>starts at 0 and grows with every measurement</td></tr><tr><td>Reset detection and threshold</td><td>yes</td><td>no</td></tr><tr><td>Start values</td><td>possible</td><td>not needed, leave them empty</td></tr><tr><td>&quot;Align meter reading&quot; (from v0.7.0)</td><td>yes</td><td>yes</td></tr><tr><td>&quot;Meter swapped&quot; (from v0.7.0)</td><td>yes</td><td>no</td></tr><tr><td>Own options</td><td>–</td><td>&quot;Ignore negative values&quot;, &quot;Average power values&quot;, &quot;Maximum gap between power values (minutes)&quot;</td></tr></tbody></table><p>A source with &quot;Each update adds its value&quot; behaves like a power source: SourceAnalytix keeps the total itself, and there is no reset detection and there are no start values.</p><p>Whether consumption from the grid or feed-in is counted does not depend on the source type but on the &quot;Cost Type&quot; of the price definition: &quot;Costs&quot; fills <code>consumed</code> and <code>costs</code>, &quot;Earnings&quot; fills <code>delivered</code> and <code>earnings</code>.</p><p>When you add a source, the wizard suggests the type from the unit in the step &quot;Type&quot;. If a device delivers both, see <a href="./../erste-schritte/erster-zaehler#datapoint-enable-meter-kwh-power">Which datapoint do I activate: meter (kWh) or power (W)?</a> to decide which datapoint to use.</p><p><strong>See also:</strong> <a href="./../hintergrund/berechnung#sourceanalytix-convert-watts-kwh">How does SourceAnalytix convert watts to kWh?</a> · <a href="#units-supported-energy-volume-weight">Which units are supported (energy, volume, weight, length)?</a> · <a href="./../hintergrund/zaehler-reset#device-reset-detected-mean-reset">What does &quot;Device reset detected&quot; mean and how does reset detection work?</a></p>',118)])])}const f=t(i,[["render",d]]);export{m as __pageData,f as default};
